  "app.salesPlay.cardUnlistedCount": countedNoun("tl", { one: "bagay na ibinibigay namin ang hindi nakalista sa alinmang antas ng kanilang pahina ng presyo", other: "bagay na ibinibigay namin ang hindi nakalista sa alinmang antas ng kanilang pahina ng presyo" }),
